		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_VALUE_MISSING,
		 "%s: invalid segment file - missing IO handle.",
		 function );

		return( -1 );
	}
/* TODO what about linen 7 */
	if( ( segment_file->io_handle->format == LIBEWF_FORMAT_ENCASE6 )
