			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_APPEND_FAILED,
			 "%s: unable to append element to sections list.",
			 function );

			goto on_error;
		}
	}
	if( ( ( segment_file->type == LIBEWF_SEGMENT_FILE_TYPE_EWF1 )
